insert into public.emission_factors (id, dataset_id, dataset_version, mode, variant, variant_label, region, value, unit, gas_metric, boundary, source_org, source_title, source_url, source_reference, published_date, effective_from, effective_to, methodology_notes, quality) values ('conv-walking-0', 'convention', '1', 'walking', 'default', 'Walking', 'ANY', 0, 'kgCO2e/pkm', 'CO2e', 'zero_direct_convention', 'Transport GHG accounting convention', 'Human-powered travel has no direct operational (fuel/electricity) emissions', 'https://www.gov.uk/government/publications/greenhouse-gas-reporting-conversion-factors-2025', null, null, null, null, 'Recorded as 0 kg CO2e for direct operational emissions, consistent with standard transport accounting. This does NOT mean the activity has zero life-cycle emissions: bicycle manufacture, infrastructure and additional food energy are excluded.', 'convention') on conflict (id) do nothing;
