insert into public.emission_factors (id, dataset_id, dataset_version, mode, variant, variant_label, region, value, unit, gas_metric, boundary, source_org, source_title, source_url, source_reference, published_date, effective_from, effective_to, methodology_notes, quality) values ('desnz25-bus-average-local-pkm', 'desnz-2025', '2025 (v1.0, published 2025-06-10)', 'bus', 'average_local', 'Average local bus', 'GB', 0.10385, 'kgCO2e/pkm', 'CO2e', 'direct_operational', 'UK Department for Energy Security and Net Zero (DESNZ)', 'Greenhouse gas reporting: conversion factors 2025 (flat file, "Business travel- land" tab)', 'https://www.gov.uk/government/publications/greenhouse-gas-reporting-conversion-factors-2025', 'ID 25_314_3145_11_1', '2025-06-10', '2025-01-01', '2025-12-31', 'Per passenger-km, based on UK average bus occupancy. Bus emissions per passenger depend strongly on occupancy; busy urban routes in Taiwan may be lower, rural routes higher.', 'official_primary') on conflict (id) do nothing;
