insert into public.emission_factors (id, dataset_id, dataset_version, mode, variant, variant_label, region, value, unit, gas_metric, boundary, source_org, source_title, source_url, source_reference, published_date, effective_from, effective_to, methodology_notes, quality) values ('desnz25-rail-national-as-hsr-pkm', 'desnz-2025', '2025 (v1.0, published 2025-06-10)', 'hsr', 'national_rail_proxy', 'High-speed rail (UK national rail proxy)', 'GB', 0.03546, 'kgCO2e/pkm', 'CO2e', 'operational_incl_electricity', 'UK Department for Energy Security and Net Zero (DESNZ)', 'Greenhouse gas reporting: conversion factors 2025 (flat file, "Business travel- land" tab)', 'https://www.gov.uk/government/publications/greenhouse-gas-reporting-conversion-factors-2025', 'ID 25_315_3147_11_1', '2025-06-10', '2025-01-01', '2025-12-31', 'DESNZ publishes no domestic high-speed-rail factor. The UK national rail factor is used as a proxy. The DESNZ "International rail" factor (Eurostar) is deliberately NOT used because it reflects the French grid.', 'official_proxy_other_region') on conflict (id) do nothing;
insert into public.emission_factor_sets (id, version, name, short_name, description, primary_region, mixed_boundaries, caveats, default_variants) values ('ecomove-tw-hybrid', '2026.10-1', 'Taiwan-first: official Taiwan rail & MRT carbon labels + UK DESNZ 2025 road factors', 'Taiwan-first (mixed boundary)', 'Uses Taiwan''s government-approved carbon-footprint label values for MRT, TRA and THSR. Taiwan-specific factors for cars, motorcycles, taxis and buses could not be verified from an official source in this release, so UK DESNZ 2025 factors are used as clearly-labelled proxies.', 'TW', true, array['MIXED ACCOUNTING BOUNDARIES: rail and MRT values are life-cycle product carbon footprints, while road values are DESNZ direct (tailpipe) factors that exclude fuel production and vehicle manufacture. Because the rail figures include more life-cycle stages, comparisons between rail and road in this set are conservative: they tend to understate, not overstate, the advantage of rail.', 'Road factors (car, motorcycle, taxi, bus) are UK fleet averages used as proxies for Taiwan.', '"Other public transport" and "Unknown" trips have no factor and are reported as unavailable.']::text[], '{"walking":"default","cycling":"default","car":"average_unknown_fuel","motorcycle":"average","taxi":"regular","bus":"average_local","metro":"taipei_metro","train":"tra_local","hsr":"thsr"}'::jsonb) on conflict (id) do update set version = excluded.version, name = excluded.name, short_name = excluded.short_name, description = excluded.description, mixed_boundaries = excluded.mixed_boundaries, caveats = excluded.caveats, default_variants = excluded.default_variants;
