insert into public.emission_factor_sets (id, version, name, short_name, description, primary_region, mixed_boundaries, caveats, default_variants) values ('desnz-2025-uk', '2025.1', 'UK DESNZ 2025 conversion factors (single source, operational boundary)', 'DESNZ 2025 (consistent boundary)', 'All factors come from one official dataset with a consistent operational boundary (direct fuel combustion plus electricity generation for electric traction; excludes well-to-tank and manufacturing). Best for like-for-like mode comparisons, but values reflect UK fleets, load factors and the UK grid.', 'GB', false, array['All values are UK averages; Taiwanese vehicles, occupancy and electricity grid differ.', 'High-speed rail uses the UK national rail factor as a proxy.', '"Other public transport" and "Unknown" trips have no factor and are reported as unavailable.']::text[], '{"walking":"default","cycling":"default","car":"average_unknown_fuel","motorcycle":"average","taxi":"regular","bus":"average_local","metro":"london_underground","train":"national_rail","hsr":"national_rail_proxy"}'::jsonb) on conflict (id) do update set version = excluded.version, name = excluded.name, short_name = excluded.short_name, description = excluded.description, mixed_boundaries = excluded.mixed_boundaries, caveats = excluded.caveats, default_variants = excluded.default_variants;
