insert into public.emission_factor_set_members (set_id, factor_id, is_regional_proxy, quality) values ('desnz-2025-uk', 'conv-cycling-0', false, 'convention') on conflict (set_id, factor_id) do update set is_regional_proxy = excluded.is_regional_proxy, quality = excluded.quality;
